function updateKeyHints(){const active=document.activeElement,focus=active?.id==='edge-reverse'?'reverse':active?.closest('.zoom-controls')?'zoom':active?.closest('#editor')?'source':active?.closest('input:not([type=checkbox]):not([type=radio]):not([type=range]),textarea,[contenteditable=true]')?'text':active?.closest('dialog[open]')?'dialog':active?.closest('#menu .context-editor')?'context':active===canvas?'canvas':'other';const hints=sequence?.hints({focus,...hintModifiers,space})||keyHints({focus,valid,sourceOnly:renderedSource===source()&&!!model?.error,...hintModifiers,space,contextGrid:!!active?.closest('.compact-shapes,.colour-swatches,.connection-types'),connecting:!!connecting,connectionTarget,nodes:selected.size,group:!!selectedGroup,edge:edgeIndex!==null,inGroup:model?.nodes.some(n=>selected.has(n.id)&&n.group)}),bar=$('#key-hints');bar.querySelector('.hint-mode').textContent=hints.mode;const items=hints.keys.map(([key,label])=>{const item=document.createElement('span');item.className='key-hint';const badge=document.createElement('kbd');badge.textContent=key;const text=document.createElement('span');text.textContent=label;item.append(badge,text);return item;});bar.querySelector('.hint-keys').replaceChildren(...items);}
