async function exportSnapshot(){
 for(const session of contextSessions)if(session.dirty)session.flush();
 const deadline=performance.now()+10000;
 while([...contextSessions].some(session=>session.dirty)||renderedSource!==source()){
  if([...contextSessions].some(session=>session.dirty&&session.state==='invalid'))throw Error('Finish the current context edit before exporting.');
  if($('#status').textContent.startsWith('Fix source'))throw Error('Fix the source before exporting.');
  if(performance.now()>deadline)throw Error('The diagram is still updating. Try exporting again in a moment.');
  await new Promise(resolve=>setTimeout(resolve,25));
 }
 return scene.querySelector('svg');
}
function exportDialog(){
 const d=$('#dialog');if(d.open)d.close();d.className='export-dialog';d.setAttribute('aria-label','Export diagram');
 d.innerHTML='<form><h2>Export diagram</h2><p class="export-note">Exports the whole diagram, without editor controls.</p><label>Format<select name="format"><option value="png">PNG image</option><option value="svg">SVG vector</option></select></label><label class="export-transparency"><input name="transparent" type="checkbox"><span>Transparent PNG background</span></label><p class="export-background-note">Otherwise, PNG uses the canvas colour.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" class="export-close">Cancel</button><button type="submit" class="primary">Download PNG</button></div></form>';
 const form=d.querySelector('form'),format=form.elements.format,transparent=form.elements.transparent,button=form.querySelector('[type=submit]'),error=form.querySelector('.error');
 format.onchange=()=>{const png=format.value==='png';form.querySelector('.export-transparency').hidden=!png;form.querySelector('.export-background-note').textContent=png?'Otherwise, PNG uses the canvas colour.':'SVG has a transparent background.';button.textContent=png?'Download PNG':'Download SVG';};
 form.querySelector('.export-close').onclick=()=>d.close();
 form.onsubmit=async event=>{event.preventDefault();button.disabled=true;format.disabled=true;transparent.disabled=true;button.textContent='Preparing…';error.textContent='';try{const svg=await exportSnapshot();if(format.value==='png')downloadBlob(await diagramPng(svg,{background:transparent.checked?null:getComputedStyle(canvas).backgroundColor}),'diagram.png');else downloadBlob((await diagramSvg(svg)).blob,'diagram.svg');d.close();canvas.focus();}catch(e){error.textContent=e.message||'Could not export this diagram.';}finally{button.disabled=false;format.disabled=false;transparent.disabled=false;button.textContent=format.value==='png'?'Download PNG':'Download SVG';}};
 d.showModal();format.focus();
}
